# Config from bundle-passed args (catalog=... gold_schema=...); safe demo fallbacks.
_args=dict(a.split("=",1) for a in sys.argv[1:] if "=" in a)
CAT=_args.get("catalog","cancer_registry_demo"); SCH=_args.get("gold_schema","cancer_gold")
spark=SparkSession.builder.getOrCreate()
schema=StructType([
 StructField("naaccr_item_id",IntegerType()),StructField("item_name",StringType()),StructField("section",StringType()),
 StructField("data_type",StringType()),StructField("length",IntegerType()),StructField("required",BooleanType()),
 StructField("valid_values",StringType()),StructField("unknown_code",StringType()),StructField("description",StringType()),
 StructField("code_system",StringType()),StructField("coding_instructions",StringType()),StructField("reference_url",StringType()),
 StructField("source",StringType()),StructField("version",StringType())])
recs=[Row(naaccr_item_id=int(r["naaccr_item_id"]),item_name=r["item_name"],section=r["section"],data_type=r["data_type"],
 length=(int(r["length"]) if r.get("length") is not None else None),required=bool(r["required"]),valid_values=r.get("valid_values"),
 unknown_code=r.get("unknown_code"),description=r.get("description"),code_system=r.get("code_system"),
 coding_instructions=r.get("coding_instructions"),reference_url=r.get("reference_url"),source=r.get("source"),version=r.get("version")) for r in ROWS]
df=spark.createDataFrame(recs,schema=schema)
df.write.format("delta").mode("overwrite").option("overwriteSchema","true").saveAsTable(f"{CAT}.{SCH}.gold_naaccr_dictionary")
spark.sql(f"ALTER TABLE {CAT}.{SCH}.gold_naaccr_dictionary SET TBLPROPERTIES (delta.enableChangeDataFeed=true)")
n=spark.table(f"{CAT}.{SCH}.gold_naaccr_dictionary").count()
print("WROTE",n,"rows; distinct ids:",spark.sql(f"SELECT COUNT(DISTINCT naaccr_item_id) c FROM {CAT}.{SCH}.gold_naaccr_dictionary").collect()[0]["c"])
